import{_ as e,o as t,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"框架模型与边界","description":"","frontmatter":{"title":"框架模型与边界","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/core/frameworks/ecosystem-landscape.md","filePath":"frontend/guide/core/frameworks/ecosystem-landscape.md","lastUpdated":1785242340000}'),i={name:"frontend/guide/core/frameworks/ecosystem-landscape.md"};function r(l,a,p,d,o,h){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="框架模型与边界" tabindex="-1">框架模型与边界 <a class="header-anchor" href="#框架模型与边界" aria-label="Permalink to &quot;框架模型与边界&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>前端框架解决的核心问题不是“把 HTML 写进 JavaScript”或“少操作几次 DOM”，而是让开发者用稳定的状态与组件关系描述界面，再由运行时或编译器把变化同步到宿主平台。理解这个模型之后，才能分清框架、路由、状态库、构建工具和全栈框架各自负责什么，也能判断一个页面是否真的需要引入完整框架。</p><p>本篇只建立 React、Vue、Svelte 等 UI 框架共有的知识地图。React 19、Vue 3 的具体组件 API、工程实践和源码机制分别由对应分组负责。</p><h2 id="_1-框架解决的问题" tabindex="-1">1. 框架解决的问题 <a class="header-anchor" href="#_1-框架解决的问题" aria-label="Permalink to &quot;1. 框架解决的问题&quot;">​</a></h2><h3 id="_1-1-状态与界面同步" tabindex="-1">1.1 状态与界面同步 <a class="header-anchor" href="#_1-1-状态与界面同步" aria-label="Permalink to &quot;1.1 状态与界面同步&quot;">​</a></h3><p>没有框架时，应用要手动维护两类状态：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内存状态：count = 2</span></span>
<span class="line"><span>DOM 状态：&lt;output&gt;2&lt;/output&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>每次数据变化都要找到正确节点、更新正确属性，并保证禁用状态、提示文案和派生结果同步变化。界面越复杂，遗漏某个更新分支的概率越高。</p><p>框架把问题改写为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UI = render(state)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>开发者声明“当前状态应得到什么界面”，框架负责追踪更新来源、调度渲染并把必要变化提交到 DOM。</p><h3 id="_1-2-交互的结构化组织" tabindex="-1">1.2 交互的结构化组织 <a class="header-anchor" href="#_1-2-交互的结构化组织" aria-label="Permalink to &quot;1.2 交互的结构化组织&quot;">​</a></h3><p>真实界面不仅有值，还包含：</p><ul><li>用户事件如何改变状态；</li><li>父子区域如何交换数据；</li><li>异步请求处于什么状态；</li><li>节点创建、更新和移除时如何管理资源；</li><li>同一逻辑如何在多个界面复用。</li></ul><p>组件、单向数据流、生命周期与组合 API 为这些关系提供共同结构。</p><h3 id="_1-3-复杂度转移" tabindex="-1">1.3 复杂度转移 <a class="header-anchor" href="#_1-3-复杂度转移" aria-label="Permalink to &quot;1.3 复杂度转移&quot;">​</a></h3><p>框架不会消除复杂度，而是把“手写 DOM 同步”转移成：</p><ul><li>状态应由谁拥有；</li><li>组件如何划分；</li><li>更新何时触发；</li><li>派生值与副作用如何区分；</li><li>服务端 HTML 与客户端状态如何一致。</li></ul><p>这些问题仍需要开发者建模，只是有了更可预测的表达方式。</p><h2 id="_2-最小运行模型" tabindex="-1">2. 最小运行模型 <a class="header-anchor" href="#_2-最小运行模型" aria-label="Permalink to &quot;2. 最小运行模型&quot;">​</a></h2><h3 id="_2-1-state" tabindex="-1">2.1 State <a class="header-anchor" href="#_2-1-state" aria-label="Permalink to &quot;2.1 State&quot;">​</a></h3><p>State 是会影响当前或未来输出的数据，例如计数、选中项、请求状态和当前用户。它必须有明确所有者，修改入口也应可追踪。</p><p>不是所有变量都应进入框架状态。不会影响渲染的缓存、DOM 引用和临时计时器通常属于普通变量或实例资源。</p><h3 id="_2-2-view-description" tabindex="-1">2.2 View Description <a class="header-anchor" href="#_2-2-view-description" aria-label="Permalink to &quot;2.2 View Description&quot;">​</a></h3><p>模板、JSX 或编译后的渲染函数都在描述界面结构：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>状态 count = 2</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>按钮“减少” + 输出“2” + 按钮“增加”</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>描述可以先产生虚拟树，也可以由编译器直接生成 DOM 更新代码。声明式 UI 不等于必须使用虚拟 DOM。</p><h3 id="_2-3-event" tabindex="-1">2.3 Event <a class="header-anchor" href="#_2-3-event" aria-label="Permalink to &quot;2.3 Event&quot;">​</a></h3><p>用户点击、输入、路由变化和网络响应形成事件。事件处理器不应直接维护多份互相独立的界面真相，而应先更新源状态，再让框架推导新界面。</p><h3 id="_2-4-update" tabindex="-1">2.4 Update <a class="header-anchor" href="#_2-4-update" aria-label="Permalink to &quot;2.4 Update&quot;">​</a></h3><p>一次典型更新：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户事件</span></span>
<span class="line"><span>  -&gt; 更新源状态</span></span>
<span class="line"><span>  -&gt; 标记受影响组件或依赖</span></span>
<span class="line"><span>  -&gt; 调度渲染</span></span>
<span class="line"><span>  -&gt; 计算新界面描述</span></span>
<span class="line"><span>  -&gt; 提交必要 DOM 变化</span></span>
<span class="line"><span>  -&gt; 执行提交后的副作用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>各框架在依赖跟踪、调度与提交方式上不同，但这条数据流可以作为共同调试地图。</p><h2 id="_3-组件树" tabindex="-1">3. 组件树 <a class="header-anchor" href="#_3-组件树" aria-label="Permalink to &quot;3. 组件树&quot;">​</a></h2><h3 id="_3-1-component" tabindex="-1">3.1 Component <a class="header-anchor" href="#_3-1-component" aria-label="Permalink to &quot;3.1 Component&quot;">​</a></h3><p>组件是具有输入、输出、内部状态和生命周期的 UI 单元。它不是“一个文件”或“一段 HTML”的同义词；是否应该拆成组件取决于职责与变化边界。</p><h3 id="_3-2-tree" tabindex="-1">3.2 Tree <a class="header-anchor" href="#_3-2-tree" aria-label="Permalink to &quot;3.2 Tree&quot;">​</a></h3><p>组件通过包含关系组成树：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App</span></span>
<span class="line"><span>├─ Header</span></span>
<span class="line"><span>├─ ProductPage</span></span>
<span class="line"><span>│  ├─ ProductGallery</span></span>
<span class="line"><span>│  ├─ Price</span></span>
<span class="line"><span>│  └─ QuantitySelector</span></span>
<span class="line"><span>└─ CartDrawer</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>树决定了数据默认从哪里传入、上下文向哪里可见，以及父组件更新可能影响哪些后代。</p><h3 id="_3-3-identity" tabindex="-1">3.3 Identity <a class="header-anchor" href="#_3-3-identity" aria-label="Permalink to &quot;3.3 Identity&quot;">​</a></h3><p>框架必须判断“这次输出中的组件”是否与上次是同一个实例。类型、树中位置和 key 通常共同参与身份判断。</p><p>身份稳定时可以保留局部状态；身份变化时旧实例会被销毁并创建新实例。列表 key、条件分支和组件类型切换因此会直接影响状态是否保留。</p><h3 id="_3-4-ownership" tabindex="-1">3.4 Ownership <a class="header-anchor" href="#_3-4-ownership" aria-label="Permalink to &quot;3.4 Ownership&quot;">​</a></h3><p>状态应由需要协调它的最低共同祖先或明确的外部 store 持有。组件树表示渲染包含关系，不一定等于业务模块、权限边界或数据依赖图。</p><h2 id="_4-ui-框架的核心职责" tabindex="-1">4. UI 框架的核心职责 <a class="header-anchor" href="#_4-ui-框架的核心职责" aria-label="Permalink to &quot;4. UI 框架的核心职责&quot;">​</a></h2><h3 id="_4-1-组件定义" tabindex="-1">4.1 组件定义 <a class="header-anchor" href="#_4-1-组件定义" aria-label="Permalink to &quot;4.1 组件定义&quot;">​</a></h3><p>框架提供定义组件、声明输入输出和组合子内容的方式。React 使用函数组件与 JSX，Vue 常使用单文件组件、模板和 Composition API；两者 API 不同，但都在建立组件契约。</p><h3 id="_4-2-状态更新" tabindex="-1">4.2 状态更新 <a class="header-anchor" href="#_4-2-状态更新" aria-label="Permalink to &quot;4.2 状态更新&quot;">​</a></h3><p>框架提供可观察状态，以及触发或安排界面更新的规则。关键问题包括：</p><ul><li>什么操作被识别为变化；</li><li>同一轮多个变化是否批处理；</li><li>派生值何时重算；</li><li>更新读取的是快照还是可变代理；</li><li>副作用在哪个阶段执行。</li></ul><h3 id="_4-3-渲染与提交" tabindex="-1">4.3 渲染与提交 <a class="header-anchor" href="#_4-3-渲染与提交" aria-label="Permalink to &quot;4.3 渲染与提交&quot;">​</a></h3><p>渲染阶段计算应得到什么界面，提交阶段把结果应用到 DOM。渲染可能被重复、暂停或放弃，因此渲染逻辑应保持纯粹；订阅、请求和 DOM 命令放在框架规定的副作用阶段。</p><h3 id="_4-4-生命周期" tabindex="-1">4.4 生命周期 <a class="header-anchor" href="#_4-4-生命周期" aria-label="Permalink to &quot;4.4 生命周期&quot;">​</a></h3><p>框架协调组件的创建、更新、停用和销毁。生命周期的价值不在于背钩子名称，而在于让外部资源与组件存活范围一致：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建订阅 &lt;-&gt; 取消订阅</span></span>
<span class="line"><span>启动计时器 &lt;-&gt; 清除计时器</span></span>
<span class="line"><span>注册监听 &lt;-&gt; 移除监听</span></span>
<span class="line"><span>发起请求 &lt;-&gt; 取消或忽略旧结果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_4-5-调度" tabindex="-1">4.5 调度 <a class="header-anchor" href="#_4-5-调度" aria-label="Permalink to &quot;4.5 调度&quot;">​</a></h3><p>框架可以合并更新、区分优先级或延后非紧急工作。调度优化改变“更新何时提交”，但不应改变业务结果；依赖同步读取 DOM 的代码要使用框架提供的提交后时机。</p><h2 id="_5-框架不负责什么" tabindex="-1">5. 框架不负责什么 <a class="header-anchor" href="#_5-框架不负责什么" aria-label="Permalink to &quot;5. 框架不负责什么&quot;">​</a></h2><h3 id="_5-1-web-平台能力" tabindex="-1">5.1 Web 平台能力 <a class="header-anchor" href="#_5-1-web-平台能力" aria-label="Permalink to &quot;5.1 Web 平台能力&quot;">​</a></h3><p>框架最终运行在 HTML、CSS、DOM、事件、URL、Fetch、Storage 和可访问性树之上。框架封装不会替代这些知识：</p><ul><li>CSS 决定布局和绘制；</li><li>浏览器决定事件默认行为；</li><li>HTTP 决定缓存与状态语义；</li><li>HTML 语义影响表单、键盘和辅助技术；</li><li>JavaScript 决定闭包、异步与内存生命周期。</li></ul><h3 id="_5-2-业务模型" tabindex="-1">5.2 业务模型 <a class="header-anchor" href="#_5-2-业务模型" aria-label="Permalink to &quot;5.2 业务模型&quot;">​</a></h3><p>框架不知道“订单是否允许取消”“价格以什么货币计算”或“谁拥有审批权限”。领域规则应由业务模块表达，而不是散落在模板条件和点击处理器中。</p><h3 id="_5-3-后端一致性" tabindex="-1">5.3 后端一致性 <a class="header-anchor" href="#_5-3-后端一致性" aria-label="Permalink to &quot;5.3 后端一致性&quot;">​</a></h3><p>客户端状态更新不代表服务端事务成功。乐观更新、幂等、并发控制、权限和数据最终一致性需要接口契约与服务端共同保证。</p><h3 id="_5-4-性能自动正确" tabindex="-1">5.4 性能自动正确 <a class="header-anchor" href="#_5-4-性能自动正确" aria-label="Permalink to &quot;5.4 性能自动正确&quot;">​</a></h3><p>框架能批处理或减少 DOM 更新，但无法自动修复：</p><ul><li>过大的组件更新范围；</li><li>重复网络请求；</li><li>不稳定 key；</li><li>主线程长任务；</li><li>图片和字体过大；</li><li>服务端响应慢；</li><li>无边界增长的缓存。</li></ul><h2 id="_6-框架、库与元框架" tabindex="-1">6. 框架、库与元框架 <a class="header-anchor" href="#_6-框架、库与元框架" aria-label="Permalink to &quot;6. 框架、库与元框架&quot;">​</a></h2><h3 id="_6-1-ui-library" tabindex="-1">6.1 UI Library <a class="header-anchor" href="#_6-1-ui-library" aria-label="Permalink to &quot;6.1 UI Library&quot;">​</a></h3><p>UI library 主要负责组件与渲染，例如 React。它可能有官方推荐的配套方案，但不一定直接规定路由、数据加载、服务端渲染和部署。</p><h3 id="_6-2-progressive-framework" tabindex="-1">6.2 Progressive Framework <a class="header-anchor" href="#_6-2-progressive-framework" aria-label="Permalink to &quot;6.2 Progressive Framework&quot;">​</a></h3><p>渐进式框架允许从页面增强逐步扩展到完整 SPA，例如 Vue。核心包负责 UI，Router、Pinia、SSR 框架等由生态补齐。</p><p>“库”和“框架”没有能解释所有产品的绝对分界，真正重要的是项目引入后由谁规定应用结构和运行生命周期。</p><h3 id="_6-3-meta-framework" tabindex="-1">6.3 Meta-framework <a class="header-anchor" href="#_6-3-meta-framework" aria-label="Permalink to &quot;6.3 Meta-framework&quot;">​</a></h3><p>元框架把 UI 框架与文件路由、服务端渲染、数据加载、构建和部署约束组合起来，例如 Next.js、Nuxt、SvelteKit。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>元框架</span></span>
<span class="line"><span>├─ UI 框架</span></span>
<span class="line"><span>├─ 路由与布局</span></span>
<span class="line"><span>├─ 服务端/客户端模块边界</span></span>
<span class="line"><span>├─ 数据加载与缓存</span></span>
<span class="line"><span>├─ 构建与代码分割</span></span>
<span class="line"><span>└─ 部署适配</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>使用元框架时，页面的缓存和执行位置往往由它决定，不能只按底层 UI 框架推断。</p><h3 id="_6-4-compiler" tabindex="-1">6.4 Compiler <a class="header-anchor" href="#_6-4-compiler" aria-label="Permalink to &quot;6.4 Compiler&quot;">​</a></h3><p>编译器把模板、JSX 或宏转换为运行时代码，也可能进行静态依赖分析和更新优化。它参与“如何实现渲染”，但不自动提供路由、服务端数据和业务状态。</p><h3 id="_6-5-toolchain" tabindex="-1">6.5 Toolchain <a class="header-anchor" href="#_6-5-toolchain" aria-label="Permalink to &quot;6.5 Toolchain&quot;">​</a></h3><p>Vite、Rspack、Babel、TypeScript、ESLint 和测试工具解决构建、转换、类型与质量问题。它们不是 UI 框架：</p><table tabindex="0"><thead><tr><th>问题</th><th>主要责任方</th></tr></thead><tbody><tr><td>状态变化后更新 DOM</td><td>UI 框架</td></tr><tr><td>模块开发服务器与产物构建</td><td>构建工具</td></tr><tr><td>静态类型检查</td><td>TypeScript</td></tr><tr><td>页面 URL 与布局</td><td>Router / 元框架</td></tr><tr><td>远程数据缓存</td><td>数据请求层</td></tr><tr><td>代码规范检查</td><td>Linter</td></tr></tbody></table><h2 id="_7-应用能力层" tabindex="-1">7. 应用能力层 <a class="header-anchor" href="#_7-应用能力层" aria-label="Permalink to &quot;7. 应用能力层&quot;">​</a></h2><h3 id="_7-1-routing" tabindex="-1">7.1 Routing <a class="header-anchor" href="#_7-1-routing" aria-label="Permalink to &quot;7.1 Routing&quot;">​</a></h3><p>路由把 URL 映射为页面、布局与数据需求。单页 Router 在浏览器处理导航；元框架还可能在服务端匹配路由。URL 本身应保持可分享、可刷新和可前进后退。</p><h3 id="_7-2-client-state" tabindex="-1">7.2 Client State <a class="header-anchor" href="#_7-2-client-state" aria-label="Permalink to &quot;7.2 Client State&quot;">​</a></h3><p>局部交互状态优先留在组件附近。只有跨距离共享、独立于某棵组件树或需要集中事件模型的数据，才需要 Context、provide/inject 或外部 store。</p><h3 id="_7-3-server-state" tabindex="-1">7.3 Server State <a class="header-anchor" href="#_7-3-server-state" aria-label="Permalink to &quot;7.3 Server State&quot;">​</a></h3><p>远程数据带有请求、缓存、过期、重试和并发语义，不只是一个全局对象。数据请求库或元框架数据层通常比通用客户端 store 更适合管理它。</p><h3 id="_7-4-forms" tabindex="-1">7.4 Forms <a class="header-anchor" href="#_7-4-forms" aria-label="Permalink to &quot;7.4 Forms&quot;">​</a></h3><p>表单同时涉及浏览器原生提交、输入状态、校验、无障碍和服务端错误。框架可以绑定值，不能替代完整表单语义。</p><h3 id="_7-5-design-system" tabindex="-1">7.5 Design System <a class="header-anchor" href="#_7-5-design-system" aria-label="Permalink to &quot;7.5 Design System&quot;">​</a></h3><p>组件库和设计系统建立视觉、交互和可访问性规范。它们运行在框架之上，不应反向成为所有业务状态的容器。</p><h2 id="_8-运行与渲染位置" tabindex="-1">8. 运行与渲染位置 <a class="header-anchor" href="#_8-运行与渲染位置" aria-label="Permalink to &quot;8. 运行与渲染位置&quot;">​</a></h2><h3 id="_8-1-browser-runtime" tabindex="-1">8.1 Browser Runtime <a class="header-anchor" href="#_8-1-browser-runtime" aria-label="Permalink to &quot;8.1 Browser Runtime&quot;">​</a></h3><p>纯客户端应用在浏览器下载 JavaScript 后创建界面。它适合登录后的高交互应用，但初始内容依赖脚本执行。</p><h3 id="_8-2-server-rendering" tabindex="-1">8.2 Server Rendering <a class="header-anchor" href="#_8-2-server-rendering" aria-label="Permalink to &quot;8.2 Server Rendering&quot;">​</a></h3><p>服务端可以先输出 HTML，浏览器再通过 hydration 接管交互。服务端渲染改善首屏内容交付，但引入双端执行、数据序列化和一致性要求。</p><h3 id="_8-3-build-time-rendering" tabindex="-1">8.3 Build-time Rendering <a class="header-anchor" href="#_8-3-build-time-rendering" aria-label="Permalink to &quot;8.3 Build-time Rendering&quot;">​</a></h3><p>构建时可以预生成稳定页面。请求直接得到现成 HTML，但更新内容需要重新构建或增量再生成。</p><h3 id="_8-4-per-route-hybrid" tabindex="-1">8.4 Per-route Hybrid <a class="header-anchor" href="#_8-4-per-route-hybrid" aria-label="Permalink to &quot;8.4 Per-route Hybrid&quot;">​</a></h3><p>现代元框架常按路由选择 CSR、SSR、SSG 或缓存再生成。项目不是只能选一个全局缩写；应根据每类页面的数据和交互约束确定。</p><p>这些模式的完整对比见“CSR、SSR、SSG 与 ISR”。</p><h2 id="_9-不使用完整框架" tabindex="-1">9. 不使用完整框架 <a class="header-anchor" href="#_9-不使用完整框架" aria-label="Permalink to &quot;9. 不使用完整框架&quot;">​</a></h2><h3 id="_9-1-静态内容" tabindex="-1">9.1 静态内容 <a class="header-anchor" href="#_9-1-静态内容" aria-label="Permalink to &quot;9.1 静态内容&quot;">​</a></h3><p>纯文档、简单活动页和少量服务端表单可能只需 HTML 与 CSS。引入大型客户端运行时会增加下载、执行和维护成本。</p><h3 id="_9-2-局部增强" tabindex="-1">9.2 局部增强 <a class="header-anchor" href="#_9-2-局部增强" aria-label="Permalink to &quot;9.2 局部增强&quot;">​</a></h3><p>页面主体由服务端输出，只有搜索建议、弹窗或购物车按钮需要交互时，可以用少量原生脚本、Web Component 或小型增强库处理局部区域。</p><h3 id="_9-3-嵌入式-widget" tabindex="-1">9.3 嵌入式 Widget <a class="header-anchor" href="#_9-3-嵌入式-widget" aria-label="Permalink to &quot;9.3 嵌入式 Widget&quot;">​</a></h3><p>需要嵌入不同宿主的独立控件要重视样式隔离、资源体积与多实例生命周期。完整 SPA Router 和全局状态通常不是它的默认需求。</p><h3 id="_9-4-框架的引入阈值" tabindex="-1">9.4 框架的引入阈值 <a class="header-anchor" href="#_9-4-框架的引入阈值" aria-label="Permalink to &quot;9.4 框架的引入阈值&quot;">​</a></h3><p>当页面出现以下关系时，框架价值开始明显：</p><ul><li>多个区域依赖同一状态；</li><li>条件、列表和表单组合复杂；</li><li>需要稳定组件复用；</li><li>页面长期演进且多人协作；</li><li>需要客户端路由和持续交互；</li><li>已选择能承担 SSR/SSG 的元框架。</li></ul><p>判断依据是状态和生命周期复杂度，而不是页面元素数量。</p><h2 id="_10-完整案例-订单列表需要哪些层" tabindex="-1">10. 完整案例：订单列表需要哪些层 <a class="header-anchor" href="#_10-完整案例-订单列表需要哪些层" aria-label="Permalink to &quot;10. 完整案例：订单列表需要哪些层&quot;">​</a></h2><p>需求：</p><ul><li>登录用户查看订单；</li><li>按状态筛选；</li><li>URL 可复制；</li><li>请求失败可重试；</li><li>列表项可取消订单；</li><li>营销首页需要可索引。</li></ul><p>职责拆分：</p><table tabindex="0"><thead><tr><th>需求</th><th>合理归属</th><th>原因</th></tr></thead><tbody><tr><td>筛选按钮与列表结构</td><td>UI 组件</td><td>描述界面与交互</td></tr><tr><td>当前筛选值</td><td>URL Router</td><td>刷新、分享和后退需要保留</td></tr><tr><td>订单请求与缓存</td><td>Server-state 层</td><td>需要过期、并发和重试</td></tr><tr><td>是否允许取消</td><td>领域规则 + 服务端</td><td>不能只由按钮显隐保证</td></tr><tr><td>取消后的局部提示</td><td>组件状态</td><td>生命周期局限于当前交互</td></tr><tr><td>营销首页 HTML</td><td>元框架 SSR/SSG</td><td>与登录后订单界面约束不同</td></tr><tr><td>TypeScript 转换</td><td>构建与类型工具</td><td>不负责运行时 UI 同步</td></tr></tbody></table><p>结果流：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>URL status=paid</span></span>
<span class="line"><span>  -&gt; Router 提供筛选参数</span></span>
<span class="line"><span>  -&gt; 数据层请求 /orders?status=paid</span></span>
<span class="line"><span>  -&gt; 组件根据 pending/error/data 渲染</span></span>
<span class="line"><span>  -&gt; 用户点击取消</span></span>
<span class="line"><span>  -&gt; 服务端鉴权并修改</span></span>
<span class="line"><span>  -&gt; 数据层失效或更新订单缓存</span></span>
<span class="line"><span>  -&gt; 组件重新得到派生界面</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这张图中，UI 框架承担状态驱动渲染与组件生命周期；它没有接管 HTTP 语义、业务权限或数据一致性。</p><h2 id="_11-验证框架边界" tabindex="-1">11. 验证框架边界 <a class="header-anchor" href="#_11-验证框架边界" aria-label="Permalink to &quot;11. 验证框架边界&quot;">​</a></h2><h3 id="_11-1-组件依赖检查" tabindex="-1">11.1 组件依赖检查 <a class="header-anchor" href="#_11-1-组件依赖检查" aria-label="Permalink to &quot;11.1 组件依赖检查&quot;">​</a></h3><p>查看一个组件是否同时直接负责：</p><ul><li>URL 解析；</li><li>Fetch 与重试；</li><li>领域规则；</li><li>DOM 命令；</li><li>全局事件；</li><li>视觉结构。</li></ul><p>若全部集中在组件中，问题不是“框架能力不足”，而是职责边界没有建立。</p><h3 id="_11-2-更新链检查" tabindex="-1">11.2 更新链检查 <a class="header-anchor" href="#_11-2-更新链检查" aria-label="Permalink to &quot;11.2 更新链检查&quot;">​</a></h3><p>在框架 DevTools 或日志中追踪：</p><ol><li>哪个事件修改了哪份源状态；</li><li>哪些派生值重新计算；</li><li>哪些组件重新渲染；</li><li>哪些 DOM 真正提交；</li><li>哪个副作用又触发了后续更新。</li></ol><p>无法回答第一步时，通常存在多份真相或隐式全局修改。</p><h3 id="_11-3-平台检查" tabindex="-1">11.3 平台检查 <a class="header-anchor" href="#_11-3-平台检查" aria-label="Permalink to &quot;11.3 平台检查&quot;">​</a></h3><p>遇到表单提交、焦点、缓存、跨域、布局或可访问性问题时，先判断它属于框架抽象还是 Web 平台。不要用更多组件封装掩盖错误 HTML 与浏览器规则。</p><h2 id="_12-常见误区" tabindex="-1">12. 常见误区 <a class="header-anchor" href="#_12-常见误区" aria-label="Permalink to &quot;12. 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确理解</th></tr></thead><tbody><tr><td>框架就是虚拟 DOM</td><td>编译式框架和细粒度响应式也可实现声明式 UI</td></tr><tr><td>使用框架就不需要 DOM/HTTP/CSS</td><td>框架最终仍依赖 Web 平台</td></tr><tr><td>所有数据都放全局 store</td><td>状态应按所有权、生命周期和数据来源分类</td></tr><tr><td>组件越小越好</td><td>拆分依据是职责与变化边界，不是行数</td></tr><tr><td>SSR 是 UI 框架自动提供</td><td>通常需要服务端运行时或元框架</td></tr><tr><td>框架能保证业务一致性</td><td>权限、事务和并发仍由接口与服务端保证</td></tr><tr><td>新项目必须先选框架</td><td>先确认交互、渲染位置和生命周期复杂度</td></tr></tbody></table><h2 id="_13-总结" tabindex="-1">13. 总结 <a class="header-anchor" href="#_13-总结" aria-label="Permalink to &quot;13. 总结&quot;">​</a></h2><ul><li>UI 框架围绕“状态 → 界面描述 → 调度 → DOM 提交”组织应用。</li><li>组件树提供输入输出、状态所有权、身份和生命周期结构。</li><li>框架不替代 Web 平台、业务规则、服务端一致性和性能分析。</li><li>Router、server-state、表单、构建工具和元框架分别补充不同应用能力。</li><li>是否使用框架取决于状态关系与生命周期复杂度；一个项目还可以按路由组合不同渲染模式。</li></ul><h2 id="_14-参考资料" tabindex="-1">14. 参考资料 <a class="header-anchor" href="#_14-参考资料" aria-label="Permalink to &quot;14. 参考资料&quot;">​</a></h2><ul><li><a href="https://react.dev/learn/describing-the-ui" target="_blank" rel="noreferrer">React：Describing the UI</a></li><li><a href="https://react.dev/learn/state-as-a-snapshot" target="_blank" rel="noreferrer">React：State as a Snapshot</a></li><li><a href="https://vuejs.org/guide/introduction.html" target="_blank" rel="noreferrer">Vue：Introduction</a></li><li><a href="https://vuejs.org/guide/essentials/reactivity-fundamentals.html" target="_blank" rel="noreferrer">Vue：Reactivity Fundamentals</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Client-side_tools/Overview" target="_blank" rel="noreferrer">MDN：Client-side tooling overview</a></li></ul>`,142)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
